/**
 * SQL Parser & Importer for Multi-Company ERP
 * Parses standard SQL dump files generated by the ERP and extracts entities
 */

export interface ParsedSQLResult {
  companiesCount: number;
  accountsCount: number;
  productsCount: number;
  customersCount: number;
  suppliersCount: number;
  vouchersCount: number;
  salesCount: number;
  purchasesCount: number;
  data: any;
}

export function parseSQLDump(sqlText: string): ParsedSQLResult {
  const result: ParsedSQLResult = {
    companiesCount: 0,
    accountsCount: 0,
    productsCount: 0,
    customersCount: 0,
    suppliersCount: 0,
    vouchersCount: 0,
    salesCount: 0,
    purchasesCount: 0,
    data: {
      companies: [],
      accounts: [],
      products: [],
      customers: [],
      suppliers: [],
      vouchers: [],
      sales: [],
      purchases: [],
    },
  };

  const lines = sqlText.split('\n');

  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.startsWith('--') || trimmed.length === 0) continue;

    // Check for INSERT INTO statements
    if (trimmed.toUpperCase().includes('INSERT INTO COMPANIES')) {
      result.companiesCount++;
    } else if (trimmed.toUpperCase().includes('INSERT INTO CHART_OF_ACCOUNTS')) {
      result.accountsCount++;
    } else if (trimmed.toUpperCase().includes('INSERT INTO PRODUCTS')) {
      result.productsCount++;
    } else if (trimmed.toUpperCase().includes('INSERT INTO CUSTOMERS')) {
      result.customersCount++;
    } else if (trimmed.toUpperCase().includes('INSERT INTO SUPPLIERS')) {
      result.suppliersCount++;
    } else if (trimmed.toUpperCase().includes('INSERT INTO VOUCHERS')) {
      result.vouchersCount++;
    } else if (trimmed.toUpperCase().includes('INSERT INTO SALES')) {
      result.salesCount++;
    } else if (trimmed.toUpperCase().includes('INSERT INTO PURCHASES')) {
      result.purchasesCount++;
    }
  }

  // Also check if JSON metadata snapshot is embedded in SQL comments
  const jsonMatch = sqlText.match(/-- JSON_SNAPSHOT_BEGIN\s*\/\*([\s\S]*?)\*\/\s*-- JSON_SNAPSHOT_END/);
  if (jsonMatch && jsonMatch[1]) {
    try {
      const parsed = JSON.parse(jsonMatch[1].trim());
      result.data = parsed;
    } catch {
      // fallback
    }
  }

  return result;
}

